edits.replacement:
  /* v16.xx, THE STYLING PASS, STAGE D: THE RUN CARD. A glass card with a soft drop shadow and a light from the top, the outcome
     word with a glow in its own colour, the feel tags as rounded pills, and LOG RUN AND RETURN as the one primary button.
     Positions, ids and every word are unchanged. */
  #root .ocwin{ border-radius:14px; border:1px solid rgba(127,146,216,.45);
    background:radial-gradient(900px 420px at 50% -12%, rgba(127,146,216,.16), transparent 62%), linear-gradient(180deg,var(--win-top),var(--win-bot));
    box-shadow:0 24px 60px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.07); }
  #root .outcome h1{ font-size:34px; text-shadow:0 0 22px currentColor, 0 3px 0 rgba(0,0,0,.5); }
  #root .tag{ border-radius:999px; padding:6px 14px; transition:background .12s, border-color .12s, color .12s; }
  #root .tag:hover{ background:rgba(127,146,216,.10); }
  #root #oc_btn{ background:linear-gradient(180deg,#ffd97f 0%,#ffb634 100%); color:#1a1408; border:1px solid #ffe9b0; border-radius:8px;
    font-weight:800; letter-spacing:.16em; box-shadow:0 8px 22px rgba(255,180,50,.22); }
  #root #oc_btn:hover{ filter:brightness(1.06); }
</style>

check:
{v:'VER',what:'stage D of the styling pass: the run card is a rounded glass card with a drop shadow, the outcome word glows, the feel tags are pills and LOG RUN AND RETURN is a gradient primary button',
 run:function(){
   var w=document.querySelector('#outcome .ocwin'), h=document.getElementById('oc_title'), b=document.getElementById('oc_btn'), tw=document.getElementById('tagwrap'), t=document.createElement('span'), bad=[], s, o=document.getElementById('outcome'), was=o&&o.classList.contains('on');
   if(!w||!h||!b||!tw) return 'SKIP: no run card here';
   t.className='tag'; t.textContent='x'; tw.appendChild(t);
   try{
     if(o&&!was) o.classList.add('on');
     s=getComputedStyle(w); if(parseFloat(s.borderTopLeftRadius)<10) bad.push('the card corners are '+s.borderTopLeftRadius); if(!/rgba\(0, 0, 0/.test(s.boxShadow)) bad.push('the card has no drop shadow');
     s=getComputedStyle(h); if(!s.textShadow||s.textShadow==='none') bad.push('the outcome word has no glow');
     s=getComputedStyle(t); if(parseFloat(s.borderTopLeftRadius)<12) bad.push('the feel tags are square ('+s.borderTopLeftRadius+')');
     s=getComputedStyle(b); if(!/gradient/.test(s.backgroundImage)) bad.push('LOG RUN AND RETURN is flat');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ tw.removeChild(t); }catch(_r){} if(o&&!was) o.classList.remove('on'); }
   return bad.length?bad.join('; '):null; }},
